#!/usr/bin/env node

'use strict'

const fs = require('fs')

function makeController (name) {

  return `'use strict'\n\n`
        + `class ${name} {\n\n`
        + `  constructor () {\n`
        + `    //param默认就是/:id，若要改变路由，则可以设置此属性，比如设置为/:name\n`
        + `    //this.param = '/:id'\n`
        + `  }\n\n`
        + `  //以下方法，若不需要，要去掉，避免无意义的路由。\n\n`
        + `  //获取资源具体内容\n`
        + `  async get (c) {\n\n`
        + `  }\n\n`
        + `  //创建资源\n`
        + `  async post (c) {\n\n`
        + `  }\n\n`
        + `  //更新资源\n`
        + `  async put (c) {\n\n`
        + `  }\n\n`
        + `  //获取列表\n`
        + `  async list (c) {\n\n`
        + `  }\n\n`
        + `  //删除资源\n`
        + `  async delete (c) {\n\n`
        + `  }\n\n`
        + `}\n\nmodule.exports = ${name}\n`

}

let name_preg = /^[a-z_][a-z0-9_]{0,50}$/i

function checkName (name) {
  return name_preg.test(name)
}

function parseNameDir (name) {
  let ind = name.indexOf('/')
  if (ind > 0) {
    return {
      dir: `/${name.substring(0, ind)}`,
      name: name.substring(ind + 1)
    }
  }

  return {
    dir : '',
    name : name
  }
}

let cdir = 'controller'

let clist = []

for (let i = 2; i < process.argv.length; i++) {
  if (process.argv[i].indexOf('--cdir=') === 0) {

    let t = process.argv[i].substring( '--cdir='.length )

    if (t.length > 0) {
      cdir = t
    }

    continue
  }

  clist.push(process.argv[i])
}

try {
  fs.accessSync(cdir) 
} catch (err) {
  fs.mkdirSync(cdir)
}

let nd 
let cpath

for (let c of clist) {

  nd = parseNameDir(c)

  if (!checkName(nd.name)) {
    console.error(`${nd.name} 不符合命名要求，要求字母数字，字母开头，支持下划线。(the name is illegal.)`)
    continue
  }

  if (nd.dir) {
    try {
      fs.accessSync(`${cdir}${nd.dir}`)
    } catch (err) {
      fs.mkdirSync(`${cdir}${nd.dir}`)
    }
  }

  cpath = `${cdir}${nd.dir}/${nd.name}.js`

  try {
    fs.accessSync(cpath)
    console.error(`${c} already at here.`)
    continue
  } catch (err) {}

  try {
    fs.writeFileSync(cpath, makeController(nd.name), {encoding: 'utf8'})
  } catch (err) {
    console.error(err)
  }

}
